Yep. Here’s a **working starting point** for an ESP32 that connects to Wi-Fi and exposes a USB serial interface so your PC can send commands to it.

One important limitation: this **doesn't make Windows see the ESP32 as a normal Wi-Fi/Bluetooth adapter**. It gives you a programmable wireless bridge that your PC can control over USB.

### ESP32 code

```cpp
#include <WiFi.h>
#include <BluetoothSerial.h>

BluetoothSerial SerialBT;

// ===== Wi-Fi credentials =====
const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

void connectWiFi() {
  Serial.println("Connecting to Wi-Fi...");

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

  int attempts = 0;

  while (WiFi.status() != WL_CONNECTED && attempts < 30) {
    delay(500);
    Serial.print(".");
    attempts++;
  }

  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("Wi-Fi connected!");
    Serial.print("IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("Wi-Fi connection failed.");
  }
}

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println();
  Serial.println("ESP32 Wireless Bridge");

  // Wi-Fi
  connectWiFi();

  // Bluetooth Classic
  if (!SerialBT.begin("ESP32-PC-BRIDGE")) {
    Serial.println("Bluetooth failed to start.");
  } else {
    Serial.println("Bluetooth started.");
    Serial.println("Device name: ESP32-PC-BRIDGE");
  }

  Serial.println();
  Serial.println("Commands:");
  Serial.println("WIFI");
  Serial.println("BT");
  Serial.println("IP");
  Serial.println("SCAN");
}

void handleCommand(String command) {
  command.trim();
  command.toUpperCase();

  if (command == "WIFI") {

    if (WiFi.status() == WL_CONNECTED) {
      Serial.println("WIFI: CONNECTED");
      Serial.print("SSID: ");
      Serial.println(WiFi.SSID());
      Serial.print("IP: ");
      Serial.println(WiFi.localIP());
      Serial.print("RSSI: ");
      Serial.println(WiFi.RSSI());
    } else {
      Serial.println("WIFI: DISCONNECTED");
    }

  } else if (command == "BT") {

    Serial.println("BLUETOOTH: ACTIVE");
    Serial.println("NAME: ESP32-PC-BRIDGE");

  } else if (command == "IP") {

    Serial.println(WiFi.localIP());

  } else if (command == "SCAN") {

    Serial.println("Scanning Wi-Fi...");

    int networks = WiFi.scanNetworks();

    for (int i = 0; i < networks; i++) {
      Serial.print(i + 1);
      Serial.print(": ");
      Serial.print(WiFi.SSID(i));
      Serial.print("  RSSI=");
      Serial.println(WiFi.RSSI(i));
    }

    WiFi.scanDelete();

  } else {

    Serial.print("Unknown command: ");
    Serial.println(command);
  }
}

void loop() {

  // Read commands from PC over USB
  if (Serial.available()) {

    String command = Serial.readStringUntil('\n');

    handleCommand(command);
  }

  // Example: receive Bluetooth data and forward it to PC
  if (SerialBT.available()) {

    String data = SerialBT.readStringUntil('\n');

    Serial.print("BT: ");
    Serial.println(data);
  }

  // Automatically reconnect Wi-Fi
  if (WiFi.status() != WL_CONNECTED) {

    static unsigned long lastAttempt = 0;

    if (millis() - lastAttempt > 10000) {

      lastAttempt = millis();

      Serial.println("Wi-Fi disconnected. Reconnecting...");

      WiFi.disconnect();
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
    }
  }
}
```

### What this gives you

Once flashed, plug the ESP32 into your PC and open the serial monitor at **115200 baud**.

You can type:

```text
WIFI
```

and get something like:

```text
WIFI: CONNECTED
SSID: MyWiFi
IP: 192.168.1.42
RSSI: -48
```

You can also type:

```text
SCAN
```

and the ESP32 will scan for nearby Wi-Fi networks.

And the ESP32 will appear to Bluetooth devices as:

**ESP32-PC-BRIDGE**

### But if your actual goal is this:

**PC → USB → ESP32 → Wi-Fi**

so that your PC can **actually use the ESP32's Wi-Fi connection as its Internet connection**, I can make the next version do that. It would essentially turn the ESP32 into a **DIY USB Wi-Fi adapter/network interface**, which is a much cooler project but requires a different USB/networking implementation.

